'use strict';

/*
 * Responsive images.
 *
 * image({ src: '/images/lion.jpg', sizes: '…' }) renders
 *
 *   <img src="…-1024.webp" srcset="…-320.webp 320w, …-640.webp 640w, …-1024.webp 1024w"
 *        sizes="…" width="1024" height="1024" alt="…" loading="lazy" decoding="async">
 *
 * using the sizes generated by `npm run images` (data/image-manifest.json) and the
 * alt text / focal point in data/images.json. It is a plain <img>, not <picture>:
 * every browser that understands srcset also understands WebP, and a JPEG
 * fallback inside <picture> was being fetched alongside the WebP by the preload
 * scanner. A src that isn't in the manifest (an external URL, say) still renders
 * a correct <img>.
 */

const registry = require('../data/images.json');
const manifest = require('../data/image-manifest.json');

const escape = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

function srcset(entry) {
  return entry.variants.map(v => `${v.url} ${v.w}w`).join(', ');
}

/**
 * @param {object} o
 * @param {string} o.src        site path of the original image
 * @param {string} [o.alt]      '' marks the image decorative; omitted -> data/images.json
 * @param {string} [o.sizes]    the `sizes` attribute (how wide it renders). Default 100vw.
 * @param {boolean} [o.eager]   above the fold: no lazy-loading
 * @param {boolean|'low'} [o.priority] true: the page's main image (eager, fetchpriority=high);
 *                              'low': off-screen-but-rendered, e.g. the slider's later slides
 * @param {string} [o.style]    extra inline CSS
 * @param {string} [o.className]
 * @param {string} [o.position] object-position override (else the registry's focal point)
 * @param {boolean} [o.fill]    stretch to the parent (object-fit: cover; width/height 100%)
 */
function image(o) {
  const entry = manifest[o.src];
  const meta = registry[o.src] || {};
  const alt = o.alt !== undefined ? o.alt : (meta.alt || '');
  const position = o.position || meta.position;

  const style = [];
  if (o.fill) style.push('display:block;width:100%;height:100%;object-fit:cover');
  if (o.style) style.push(o.style);
  if (position) style.push(`object-position:${position}`);

  // src is only the last-resort candidate (and what a lightbox / "save image" sees):
  // the largest generated size.
  const attrs = [`src="${escape(entry ? entry.variants[entry.variants.length - 1].url : o.src)}"`];
  if (entry) {
    attrs.push(`srcset="${escape(srcset(entry))}"`, `sizes="${escape(o.sizes || '100vw')}"`);
    attrs.push(`width="${entry.width}"`, `height="${entry.height}"`);
  }
  attrs.push(`alt="${escape(alt)}"`);
  if (o.className) attrs.push(`class="${escape(o.className)}"`);
  if (style.length) attrs.push(`style="${escape(style.join(';'))}"`);
  if (o.priority === true) attrs.push('fetchpriority="high"');
  else if (o.priority === 'low') attrs.push('loading="lazy"', 'fetchpriority="low"');
  else if (!o.eager) attrs.push('loading="lazy"');
  attrs.push('decoding="async"');

  if (!entry && o.src.startsWith('/')) unregistered.add(o.src);
  return `<img ${attrs.join(' ')}>`;
}

// 1200×630 social-share crop when we have one, else the image itself
function og(src) {
  return (manifest[src] && manifest[src].og) || src;
}

// "Sarah M." -> "SM", "James & Rachel T." -> "JR"
function initials(name) {
  const words = String(name || '').split(/[^A-Za-zÀ-ɏ]+/).filter(Boolean);
  return (words[0] ? words[0][0] : '') + (words.length > 1 ? words[1][0] : '');
}

// Local images that were rendered without being in data/images.json +
// data/image-manifest.json (no alt text, no responsive sizes). The static build
// fails if this isn't empty.
const unregistered = new Set();

module.exports = { image, og, initials, unregistered, manifest, registry };
